for k,rep in [('orders',(10890,10520)),('revenue_gbp',(462300,418900)),('active_customers',(39580,39240))]:
  print(k,t(a,k),t(b,k),(t(b,k)/t(a,k)-1)*100,(rep[1]/rep[0]-1)*100)
"

